def sim(inp, delov=True):
    H,W=len(inp),len(inp[0])
    objs=comps2(inp)
    # process from most top-left to least
    objs.sort(key=lambda o:(min(r for r,_ in o[1]), min(c for _,c in o[1])))
    g=[[0]*W for _ in range(H)]
    stat=[]  # list of placed objects with current cells
    for col,cells in objs:
        cur=set(cells)
        while True:
            tgt={(r-1,c-1) for r,c in cur}
            bad=False
            for t in tgt:
                if not(0<=t[0]<H and 0<=t[1]<W): bad=True; break
                if g[t[0]][t[1]]!=0: bad=True; break
            if bad: break
            cur=tgt
        # overlaps with previously placed: resolve
        for r,c in sorted(cur):
            if g[r][c]!=0:
                if delov: cur.discard((r,c))
            else: g[r][c]=col
        stat.append((col,cur))
    for col,cur in stat:
        for r,c in cur: g[r][c]=col
