# hypothesis: sequential placement into final staircase; each object stops when its next diagonal step
# would make it overlap ANY placed object OR leave grid; overlaps resolved by overwriting later-drawn onto earlier;
# draws processed bottom-right-most first (max sum of max row&col ascending key = smallest first drawn).
def solve(inp):
    Hh,Ww=len(inp),len(inp[0])
    objs=comps(inp)
    objs.sort(key=lambda o:-max(max(r for r,_ in o[1]), max(c for _,c in o[1])))  # BR furthest last -> draw earliest
    g=[[0]*Ww for _ in range(Hh)]
    for col,cells in objs:
        cur=set(cells)
        while True:
            tgt={(r-1,c-1) for r,c in cur}
            if any(not(0<=r<Hh and 0<=c<Ww) or g[r][c]!=0 for r,c in tgt): break
            cur=tgt
        for r,c in sorted(cur): g[r][c]=col
    return g

