def comps(g):
    Hh,Ww=len(g),len(g[0]); seen=set(); out=[]
    for i in range(Hh):
        for j in range(Ww):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j]; st=[(i,j)]; cells=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or g[a][b]!=col: continue
                    seen.add((a,b)); cells.add((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<Hh and 0<=y<Ww and (x,y) not in seen and g[x][y]==col: st.append((x,y))
                out.append([col,cells])
    return out

def solve_generic(inp, order_key, rev, step, coll, trim):
    Hh,Ww=len(inp),len(inp[0])
    objs=comps(inp)
    objs.sort(key=order_key, reverse=rev)
    g=[[0]*Ww for _ in range(Hh)]
    stat=[]
    for col,cells in objs:
        cur=set(cells)
        cur_cands=[]
        # step mode: 'diag','upthenleft','leftthenup'
        if step=='diag':
            while True:
                tgt={(r-1,c-1) for r,c in cur}
                if any(not(0<=r<Hh and 0<=c<Ww) or (g[r][c]!=0 and coll=='strict') for r,c in tgt): break
                cur=tgt
        elif step=='upthenleft':
            while True:
                tgt={(r-1,c) for r,c in cur}
                if any(not(0<=r<Hh and 0<=c<Ww) or (g[r][c]!=0 and coll=='strict') for r,c in tgt): break
                cur=tgt
            while True:
                tgt={(r,c-1) for r,c in cur}
                if any(not(0<=r<Hh and 0<=c<Ww) or (g[r][c]!=0 and coll=='strict') for r,c in tgt): break
                cur=tgt
        elif step=='leftthenup':
            while True:
                tgt={(r,c-1) for r,c in cur}
                if any(not(0<=r<Hh and 0<=c<Ww) or (g[r][c]!=0 and coll=='strict') for r,c in tgt): break
                cur=tgt
            while True:
                tgt={(r-1,c) for r,c in cur}
                if any(not(0<=r<Hh and 0<=c<Ww) or (g[r][c]!=0 and coll=='strict') for r,c in tgt): break
                cur=tgt
        # trim: remove overlap cells with already-placed
        delcells={t for t in cur if g[t[0]][t[1]]!=0 and g[t[0]][t[1]]!=col}
        if trim=='BR':
            br=(max(r for r,_ in cur), max(c for _,c in cur))
            if br in delcells: delcells.discard(br)
        cur-=delcells
        stat.append((col,sorted(cur)))
        for r,c in cur: g[r][c]=col
    return g,stat

