# Demo grids here are embedded in message content strings, e.g. "text":"[[7,..." 
def dig():
    G={}
    for m in re.finditer(r'"[^"]*?"\s*(?:\[|=\[)', t):
        pass
    # simpler: find 'input [[' occurrences followed by list ending ']]' then ',' or newline
    for m in re.finditer(r'(Demo pair \d+ (input|output)|Test input) \[\[(.*?)\]\]',t.replace('\\n','\n')):
        k=m[1]; body=m[3]
        try: g=json.loads(body)
        except Exception as e: continue
        if isinstance(g,list) and len(g)>1 and all(isinstance(r,list) for r in g) and all(len(r)==len(g[0]) for r in g):
            G.setdefault(k,m[1]); break
    return G
