import collections
# Build G from all session logs, deduplicating identical grids by comparing; keep only first occurrence
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    txt=''
    for f in sorted(glob.glob(d+'/../../sessions/*.jsonl')):
        txt += open(f).read().replace('\\n','\n')
    G=collections.defaultdict(list)
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',txt):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in txt[m.end():].split('\n')[:h]]
        if len(rows)==h and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            g=[[int(x) for x in r] for r in rows]
            # dedupe same grid appearing multiple times
            if not any(id(a_)==id(g) for a_ in []): 
                pass
            if len(G[k])==0 or G[k][0]!=g:
                G[k].append(g)
    return G
